# Hindi / Gujarati text for Political Science Ch 1 lesson, sections 4-5.
TEXT_B = {
 "s4.thm.title": ("सत्ता बाँटने के चार तरीक़े", "સત્તા વહેંચવાની ચાર રીતો"),
 "s4.thm.body": (
  "सत्ता की साझेदारी का विचार **अविभाजित राजनीतिक सत्ता** की अवधारणा के विरोध में उभरा। लंबे समय तक माना जाता था कि सरकार की सारी शक्ति एक व्यक्ति या एक जगह स्थित व्यक्ति-समूह के पास होनी चाहिए। आधुनिक लोकतंत्रों में सत्ता अनेक तरीक़ों से बाँटी जाती है:\n\n"
  "1. **सत्ता का क्षैतिज वितरण (सरकार के विभिन्न अंगों में):** सत्ता **विधायिका, कार्यपालिका और न्यायपालिका** में बँटी होती है, जो एक ही स्तर पर रहकर अलग-अलग शक्तियों का प्रयोग करते हैं। इस बँटवारे से कोई भी अंग **असीमित शक्ति** का प्रयोग नहीं कर पाता; हर अंग दूसरे पर **अंकुश** रखता है। इसे **नियंत्रण और संतुलन** की व्यवस्था कहते हैं। "
  "उदाहरण के लिए, भारत में कार्यपालिका (मंत्री और अधिकारी) सत्ता का प्रयोग करती है, पर वह **संसद या विधानसभाओं के प्रति उत्तरदायी** है; इसी प्रकार, न्यायाधीशों की नियुक्ति कार्यपालिका करती है, पर वे **कार्यपालिका के कामकाज या विधायिका द्वारा बनाए क़ानूनों पर अंकुश** लगा सकते हैं।\n"
  "2. **सत्ता का ऊर्ध्वाधर वितरण (सरकार के विभिन्न स्तरों में):** पूरे देश के लिए एक सामान्य सरकार (**केंद्रीय या संघ सरकार**) और प्रांतीय या क्षेत्रीय स्तर पर सरकारें (भारत में **राज्य सरकारें**)। पूरे देश के लिए ऐसी सामान्य सरकार को प्रायः **संघीय सरकार** कहते हैं। यही सिद्धांत **राज्य से निचले स्तर** तक, जैसे **नगरपालिका और पंचायत**, बढ़ाया जा सकता है।\n"
  "3. **विभिन्न सामाजिक समूहों में सत्ता की साझेदारी**, जैसे धार्मिक और भाषायी समूह। बेल्जियम की **'सामुदायिक सरकार'** इसका अच्छा उदाहरण है। कुछ देशों में संवैधानिक और क़ानूनी व्यवस्था है जिससे **सामाजिक रूप से कमज़ोर वर्गों और महिलाओं** को विधायिका और प्रशासन में हिस्सेदारी मिलती है, जैसे भारत में **आरक्षित चुनाव क्षेत्र**। इससे अल्पसंख्यक समुदायों को सरकार में जगह मिलती है।\n"
  "4. **राजनीतिक दलों, दबाव समूहों और आंदोलनों में सत्ता की साझेदारी:** लोकतंत्र में नागरिकों को सत्ता के विभिन्न दावेदारों में से चुनने की आज़ादी होनी चाहिए। **दलों के बीच प्रतिद्वंद्विता** सुनिश्चित करती है कि सत्ता एक हाथ में न रहे; लंबे समय में सत्ता विभिन्न विचारधाराओं और सामाजिक समूहों वाले दलों में बँटती है। "
  "कभी-कभी यह साझेदारी सीधी होती है, जब दो या अधिक दल मिलकर चुनाव लड़ते और **गठबंधन सरकार** बनाते हैं। **व्यापारी, उद्योगपति, किसान और औद्योगिक मज़दूर** जैसे हित समूह भी सरकारी समितियों में भागीदारी करके या फ़ैसलों को प्रभावित करके सत्ता में हिस्सेदार बनते हैं।",
  "સત્તાની ભાગીદારીનો વિચાર **અવિભાજિત રાજકીય સત્તા**ના ખ્યાલના વિરોધમાં ઊભર્યો. લાંબા સમય સુધી માનવામાં આવતું કે સરકારની બધી સત્તા એક વ્યક્તિ કે એક જગ્યાએ રહેલા જૂથ પાસે હોવી જોઈએ. આધુનિક લોકશાહીમાં સત્તા અનેક રીતે વહેંચાય છે:\n\n"
  "1. **સત્તાની આડી વહેંચણી (સરકારનાં જુદાં જુદાં અંગો વચ્ચે):** સત્તા **ધારાસભા, કારોબારી અને ન્યાયતંત્ર** વચ્ચે વહેંચાય છે, જે એક જ સ્તરે રહીને જુદી જુદી સત્તાઓનો ઉપયોગ કરે છે. આ વહેંચણીથી કોઈ અંગ **અમર્યાદિત સત્તા** વાપરી શકતું નથી; દરેક અંગ બીજા પર **અંકુશ** રાખે છે. તેને **નિયંત્રણ અને સંતુલન**ની વ્યવસ્થા કહે છે. "
  "ઉદાહરણ તરીકે, ભારતમાં કારોબારી (પ્રધાનો અને અધિકારીઓ) સત્તા વાપરે છે, પણ તે **સંસદ કે રાજ્ય વિધાનસભાને જવાબદાર** છે; એ જ રીતે, ન્યાયાધીશોની નિમણૂક કારોબારી કરે છે, છતાં તેઓ **કારોબારીના કામકાજ કે ધારાસભાએ ઘડેલા કાયદા પર અંકુશ** રાખી શકે છે.\n"
  "2. **સત્તાની ઊભી વહેંચણી (સરકારના જુદા જુદા સ્તરો વચ્ચે):** આખા દેશ માટે એક સામાન્ય સરકાર (**કેન્દ્ર કે સંઘ સરકાર**) અને પ્રાંતીય કે પ્રાદેશિક સ્તરે સરકારો (ભારતમાં **રાજ્ય સરકારો**). આખા દેશ માટેની આવી સામાન્ય સરકારને સામાન્ય રીતે **સમવાયી (સંઘીય) સરકાર** કહે છે. આ જ સિદ્ધાંત **રાજ્યથી નીચલા સ્તરે**, જેમ કે **નગરપાલિકા અને પંચાયત** સુધી, લંબાવી શકાય.\n"
  "3. **જુદાં જુદાં સામાજિક જૂથો વચ્ચે સત્તાની ભાગીદારી**, જેમ કે ધાર્મિક અને ભાષાકીય જૂથો. બેલ્જિયમની **'સમુદાય સરકાર'** તેનું સારું ઉદાહરણ છે. કેટલાક દેશોમાં બંધારણીય અને કાનૂની વ્યવસ્થા છે જેથી **સામાજિક રીતે નબળા વર્ગો અને સ્ત્રીઓ**ને ધારાસભા અને વહીવટમાં પ્રતિનિધિત્વ મળે, જેમ કે ભારતમાં **અનામત મતવિસ્તારો**. તેનાથી લઘુમતી સમુદાયોને સરકારમાં સ્થાન મળે છે.\n"
  "4. **રાજકીય પક્ષો, દબાણ જૂથો અને આંદોલનો વચ્ચે સત્તાની ભાગીદારી:** લોકશાહીમાં નાગરિકોને સત્તાના જુદા જુદા દાવેદારોમાંથી પસંદગીની સ્વતંત્રતા હોવી જોઈએ. **પક્ષો વચ્ચેની સ્પર્ધા** સુનિશ્ચિત કરે છે કે સત્તા એક હાથમાં ન રહે; લાંબા ગાળે સત્તા જુદી જુદી વિચારધારા અને સામાજિક જૂથોવાળા પક્ષોમાં વહેંચાય છે. "
  "ક્યારેક આ ભાગીદારી સીધી હોય છે, જ્યારે બે કે વધુ પક્ષો જોડાણ કરીને ચૂંટણી લડે અને **ગઠબંધન (સંયુક્ત) સરકાર** રચે. **વેપારીઓ, ઉદ્યોગપતિઓ, ખેડૂતો અને ઔદ્યોગિક કામદારો** જેવાં હિત જૂથો પણ સરકારી સમિતિઓમાં ભાગ લઈને કે નિર્ણયો પર પ્રભાવ પાડીને સત્તામાં ભાગીદાર બને છે."),
 "s4.table.title": ("सत्ता की साझेदारी के रूप", "સત્તાની ભાગીદારીનાં સ્વરૂપો"),
 "s4.table.body": (
  "| सत्ता की साझेदारी का रूप | अर्थ | उदाहरण |\n|---|---|---|\n| **क्षैतिज**: सरकार के अंगों में | एक ही स्तर पर विधायिका, कार्यपालिका और न्यायपालिका; नियंत्रण और संतुलन | न्यायाधीश विधायिका के क़ानूनों पर अंकुश रखते हैं |\n"
  "| **ऊर्ध्वाधर**: सरकार के विभिन्न स्तरों में | संघ, राज्य और स्थानीय सरकारें | संघीय सरकार; पंचायत और नगरपालिका |\n"
  "| **सामाजिक समूहों में** | धार्मिक और भाषायी समूह, कमज़ोर वर्ग, महिलाएँ | बेल्जियम की 'सामुदायिक सरकार'; भारत में आरक्षित चुनाव क्षेत्र |\n"
  "| **दलों, दबाव समूहों और आंदोलनों में** | प्रतिद्वंद्विता और गठबंधन; हित समूहों का प्रभाव | गठबंधन सरकार; व्यापारियों, किसानों और मज़दूरों के समूह |",
  "| સત્તાની ભાગીદારીનું સ્વરૂપ | અર્થ | ઉદાહરણ |\n|---|---|---|\n| **આડી**: સરકારનાં અંગો વચ્ચે | એક જ સ્તરે ધારાસભા, કારોબારી અને ન્યાયતંત્ર; નિયંત્રણ અને સંતુલન | ન્યાયાધીશો ધારાસભાના કાયદા પર અંકુશ રાખે છે |\n"
  "| **ઊભી**: સરકારના જુદા જુદા સ્તરો વચ્ચે | સંઘ, રાજ્ય અને સ્થાનિક સરકારો | સમવાયી સરકાર; પંચાયત અને નગરપાલિકા |\n"
  "| **સામાજિક જૂથો વચ્ચે** | ધાર્મિક અને ભાષાકીય જૂથો, નબળા વર્ગો, સ્ત્રીઓ | બેલ્જિયમની 'સમુદાય સરકાર'; ભારતમાં અનામત મતવિસ્તારો |\n"
  "| **પક્ષો, દબાણ જૂથો અને આંદોલનો વચ્ચે** | સ્પર્ધા અને જોડાણ; હિત જૂથોનો પ્રભાવ | ગઠબંધન સરકાર; વેપારીઓ, ખેડૂતો અને કામદારોનાં જૂથો |"),
 "s5.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s5.memory.body": (
  "- **बेल्जियम के आँकड़े: \"59-40-1 और 80-20\"**: 59% डच (फ्लेमिश), 40% फ़्रेंच (वेलोनिया), 1% जर्मन; ब्रसेल्स 80% फ़्रेंच, 20% डच।\n"
  "- **श्रीलंका के आँकड़े: \"74-18-13\"**: 74% सिंहली, 18% तमिल, 13% श्रीलंकाई तमिल।\n- **श्रीलंका की समयरेखा: 1948 स्वतंत्रता → 1956 केवल सिंहली → 1980 का दशक तमिल ईलम की माँग → 2009 गृहयुद्ध समाप्त।**\n"
  "- **बेल्जियम मॉडल: \"बराबर, राज्य, ब्रसेल्स, समुदाय\"** (बराबर मंत्री, राज्यों को अधिकार, ब्रसेल्स की बराबर सरकार, सामुदायिक सरकार)।\n"
  "- **दो तर्क: युक्तिपरक = शांति (बेहतर परिणाम); नैतिक = लोकतंत्र की आत्मा (अपना महत्त्व)।**\n- **चार रूप: \"क्षै-ऊ-स-द\"** = क्षैतिज, ऊर्ध्वाधर, सामाजिक समूह, दल।",
  "- **બેલ્જિયમના આંકડા: \"59-40-1 અને 80-20\"**: 59% ડચ (ફ્લેમિશ), 40% ફ્રેન્ચ (વૉલોનિયા), 1% જર્મન; બ્રસેલ્સ 80% ફ્રેન્ચ, 20% ડચ.\n"
  "- **શ્રીલંકાના આંકડા: \"74-18-13\"**: 74% સિંહાલી, 18% તમિળ, 13% શ્રીલંકન તમિળ.\n- **શ્રીલંકાની સમયરેખા: 1948 સ્વતંત્રતા → 1956 ફક્ત સિંહાલી → 1980નો દાયકો તમિળ ઇલમની માગણી → 2009 આંતરવિગ્રહ પૂરો.**\n"
  "- **બેલ્જિયમ મૉડલ: \"સરખા, રાજ્યો, બ્રસેલ્સ, સમુદાય\"** (સરખા પ્રધાનો, રાજ્યોને સત્તા, બ્રસેલ્સની સમાન સરકાર, સમુદાય સરકાર).\n"
  "- **બે કારણો: વ્યવહારુ = શાંતિ (સારાં પરિણામો); નૈતિક = લોકશાહીનો આત્મા (આંતરિક મૂલ્ય).**\n- **ચાર સ્વરૂપ: \"આ-ઊ-સા-પ\"** = આડી, ઊભી, સામાજિક જૂથો, પક્ષો."),
 "s5.mistakes.title": ("आम ग़लतियाँ", "સામાન્ય ભૂલો"),
 "s5.mistakes.body": (
  "1. बेल्जियम के आँकड़े उलट देना: **59% डच** बोलते हैं (फ्लेमिश इलाक़ा), **40% फ़्रेंच** (वेलोनिया); ब्रसेल्स में **80% फ़्रेंच** बोलते हैं।\n2. कहना कि बेल्जियम में फ़्रेंच भाषी बहुसंख्यक थे: वे **अल्पसंख्यक** थे, पर अधिक धनी और ताक़तवर।\n"
  "3. 1956 के क़ानून को तमिल भाषा का क़ानून कहना: इसने **सिंहली को एकमात्र राजभाषा** बनाया।\n4. युक्तिपरक (बेहतर परिणाम) और नैतिक (अपना महत्त्व) तर्कों को मिलाना।\n"
  "5. कहना कि क्षैतिज साझेदारी सरकार के स्तरों में है: क्षैतिज **अंगों** में है; ऊर्ध्वाधर **स्तरों** में।\n6. कहना कि श्रीलंका का गृहयुद्ध 1983 में समाप्त हुआ: यह **2009** में समाप्त हुआ।",
  "1. બેલ્જિયમના આંકડા ઊલટાવવા: **59% ડચ** બોલે છે (ફ્લેમિશ પ્રદેશ), **40% ફ્રેન્ચ** (વૉલોનિયા); બ્રસેલ્સમાં **80% ફ્રેન્ચ** બોલે છે.\n2. કહેવું કે બેલ્જિયમમાં ફ્રેન્ચ ભાષી બહુમતીમાં હતા: તેઓ **લઘુમતી** હતા, પણ વધુ ધનિક અને શક્તિશાળી.\n"
  "3. 1956ના કાયદાને તમિળ ભાષાનો કાયદો કહેવો: તેણે **સિંહાલીને એકમાત્ર રાજભાષા** બનાવી.\n4. વ્યવહારુ (સારાં પરિણામો) અને નૈતિક (આંતરિક મૂલ્ય) કારણોને ભેળવવાં.\n"
  "5. કહેવું કે આડી ભાગીદારી સરકારના સ્તરો વચ્ચે છે: આડી **અંગો** વચ્ચે છે; ઊભી **સ્તરો** વચ્ચે.\n6. કહેવું કે શ્રીલંકાનો આંતરવિગ્રહ 1983માં પૂરો થયો: તે **2009**માં પૂરો થયો."),
 "s5.tip.title": ("कक्षा में करके देखें", "વર્ગમાં કરી જુઓ"),
 "s5.tip.body": (
  "कक्षा को एक 'बहुसंख्यक' और एक 'अल्पसंख्यक' समूह में बाँटें और उन्हें दो बार पिकनिक का स्थान तय करने दें: एक बार सामान्य बहुमत से, और एक बार ऐसे नियम से जिसमें दोनों समूहों की सहमति ज़रूरी हो। "
  "चर्चा करें कि पूरी कक्षा ने कौन-सा फ़ैसला अधिक ख़ुशी से माना, और इसे बेल्जियम तथा श्रीलंका से जोड़ें।",
  "વર્ગને એક 'બહુમતી' અને એક 'લઘુમતી' જૂથમાં વહેંચો અને તેમને બે વાર પિકનિકનું સ્થળ નક્કી કરવા દો: એક વાર સાદી બહુમતીથી, અને એક વાર એવા નિયમથી જેમાં બંને જૂથોની સંમતિ જરૂરી હોય. "
  "ચર્ચા કરો કે આખા વર્ગે કયો નિર્ણય વધુ ખુશીથી સ્વીકાર્યો, અને તેને બેલ્જિયમ અને શ્રીલંકા સાથે જોડો."),
 "s5.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s5.reflection.body": (
  "अपने स्कूल या आवासीय सोसाइटी के बारे में सोचिए। वहाँ दिखने वाली क्षैतिज साझेदारी, ऊर्ध्वाधर साझेदारी और समूहों में साझेदारी का एक-एक उदाहरण दीजिए।",
  "તમારી શાળા કે રહેણાક સોસાયટી વિશે વિચારો. ત્યાં દેખાતી આડી ભાગીદારી, ઊભી ભાગીદારી અને જૂથો વચ્ચેની ભાગીદારીનું એક-એક ઉદાહરણ આપો."),
 "s5.connection.title": ("आगे कहाँ", "આગળ ક્યાં"),
 "s5.connection.body": (
  "- **अध्याय 2 (संघवाद):** भारत में सत्ता का ऊर्ध्वाधर वितरण।\n- **अध्याय 3 (जाति, धर्म और लैंगिक मसले):** सामाजिक समूहों और महिलाओं के साथ सत्ता की साझेदारी।\n"
  "- **अध्याय 4 (राजनीतिक दल):** प्रतिद्वंद्विता और गठबंधन।\n- **अध्याय 5 (लोकतंत्र के परिणाम):** सामाजिक विविधता का समायोजन।",
  "- **પ્રકરણ 2 (સમવાયતંત્ર):** ભારતમાં સત્તાની ઊભી વહેંચણી.\n- **પ્રકરણ 3 (જાતિ, ધર્મ અને જ્ઞાતિ):** સામાજિક જૂથો અને સ્ત્રીઓ સાથે સત્તાની ભાગીદારી.\n"
  "- **પ્રકરણ 4 (રાજકીય પક્ષો):** સ્પર્ધા અને ગઠબંધન.\n- **પ્રકરણ 5 (લોકશાહીનાં પરિણામો):** સામાજિક વિવિધતાનું સમાધાન."),
 "s5.mastery.title": ("महारत चुनौती", "નિપુણતા પડકાર"),
 "s5.mastery.body": (
  "'बेल्जियम और श्रीलंका विविधता से निपटने के दो अलग तरीक़े दिखाते हैं।' लगभग 120 शब्दों में तुलना कीजिए।\n\n"
  "**आदर्श उत्तर:** बेल्जियम ने क्षेत्रीय और सांस्कृतिक अंतरों को स्वीकार किया और 1970 से 1993 के बीच संविधान में चार संशोधन किए। उसने डच और फ़्रेंच भाषी मंत्रियों की संख्या बराबर की, राज्य सरकारों को अधिकार दिए, बराबर प्रतिनिधित्व वाली ब्रसेल्स सरकार बनाई, और संस्कृति, शिक्षा और भाषा के लिए सामुदायिक सरकारें बनाईं। "
  "इस समायोजन से गृहयुद्ध टला, देश एकजुट रहा, और ब्रसेल्स यूरोपीय संघ का मुख्यालय बना। श्रीलंका ने बहुसंख्यकवाद अपनाया: 1956 के क़ानून ने सिंहली को एकमात्र राजभाषा बनाया, नौकरियों और विश्वविद्यालयों में सिंहलियों को प्राथमिकता दी गई, और सरकार को बौद्ध मत की रक्षा करनी थी। "
  "तमिलों ने बेगानापन महसूस किया, तमिल ईलम की माँग की, और गृहयुद्ध हुआ। सत्ता की साझेदारी एकता बनाती है; बहुसंख्यकवाद उसे नष्ट करता है।",
  "'બેલ્જિયમ અને શ્રીલંકા વિવિધતા સાથે કામ પાર પાડવાની બે જુદી રીતો બતાવે છે.' આશરે 120 શબ્દોમાં સરખામણી કરો.\n\n"
  "**આદર્શ ઉત્તર:** બેલ્જિયમે પ્રાદેશિક અને સાંસ્કૃતિક તફાવતો સ્વીકાર્યા અને 1970થી 1993 વચ્ચે બંધારણમાં ચાર સુધારા કર્યા. તેણે ડચ અને ફ્રેન્ચ ભાષી પ્રધાનોની સંખ્યા સરખી કરી, રાજ્ય સરકારોને સત્તા આપી, સમાન પ્રતિનિધિત્વવાળી બ્રસેલ્સ સરકાર બનાવી, અને સંસ્કૃતિ, શિક્ષણ અને ભાષા માટે સમુદાય સરકારો રચી. "
  "આ સમાધાનથી નાગરિક સંઘર્ષ ટળ્યો, દેશ એક રહ્યો, અને બ્રસેલ્સ યુરોપિયન સંઘનું મુખ્ય મથક બન્યું. શ્રીલંકાએ બહુમતીવાદ અપનાવ્યો: 1956ના કાયદાએ સિંહાલીને એકમાત્ર રાજભાષા બનાવી, નોકરીઓ અને યુનિવર્સિટીઓમાં સિંહાલીઓને પ્રાધાન્ય અપાયું, અને રાજ્યે બૌદ્ધ ધર્મનું રક્ષણ કરવાનું હતું. "
  "તમિળોએ અલગાવ અનુભવ્યો, તમિળ ઇલમની માગણી કરી, અને આંતરવિગ્રહ થયો. સત્તાની ભાગીદારી એકતા બાંધે છે; બહુમતીવાદ તેનો નાશ કરે છે."),
 "s5.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s5.summary.body": (
  "- बेल्जियम (59% डच, 40% फ़्रेंच, 1% जर्मन) में तनाव था क्योंकि फ़्रेंच भाषी अल्पसंख्यक अधिक धनी और ताक़तवर थे।\n"
  "- श्रीलंका (74% सिंहली, 18% तमिल) ने 1948 के बाद बहुसंख्यकवादी उपाय अपनाए, जिससे तमिलों में बेगानापन आया और गृहयुद्ध हुआ (2009 में समाप्त)।\n"
  "- बेल्जियम ने बराबर मंत्रियों, राज्यों को अधिकार, बराबर ब्रसेल्स सरकार और सामुदायिक सरकारों से विविधता का समायोजन किया।\n"
  "- सत्ता की साझेदारी युक्तिपरक कारणों (कम टकराव, स्थायित्व) और नैतिक कारणों (लोकतंत्र की आत्मा) से वांछनीय है।\n"
  "- रूप: क्षैतिज (अंग), ऊर्ध्वाधर (स्तर), सामाजिक समूहों में, और दलों, दबाव समूहों और आंदोलनों में।",
  "- બેલ્જિયમ (59% ડચ, 40% ફ્રેન્ચ, 1% જર્મન)માં તણાવ હતો કારણ કે ફ્રેન્ચ ભાષી લઘુમતી વધુ ધનિક અને શક્તિશાળી હતી.\n"
  "- શ્રીલંકા (74% સિંહાલી, 18% તમિળ)એ 1948 પછી બહુમતીવાદી પગલાં અપનાવ્યાં, જેથી તમિળોમાં અલગાવ આવ્યો અને આંતરવિગ્રહ થયો (2009માં પૂરો).\n"
  "- બેલ્જિયમે સરખા પ્રધાનો, રાજ્યોને સત્તા, સમાન બ્રસેલ્સ સરકાર અને સમુદાય સરકારોથી વિવિધતાનું સમાધાન કર્યું.\n"
  "- સત્તાની ભાગીદારી વ્યવહારુ કારણો (ઓછો સંઘર્ષ, સ્થિરતા) અને નૈતિક કારણો (લોકશાહીનો આત્મા)થી ઇચ્છનીય છે.\n"
  "- સ્વરૂપો: આડી (અંગો), ઊભી (સ્તરો), સામાજિક જૂથો વચ્ચે, અને પક્ષો, દબાણ જૂથો અને આંદોલનો વચ્ચે."),
 "s5.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટેની ટિપ્સ"),
 "s5.examtips.body": (
  "- 2025-26 के प्रतिदर्श प्रश्न-पत्र में पूछा गया कि बेल्जियम की जातीय बनावट के कौन-से कथन सही हैं (1% जर्मन; ब्रसेल्स 80% फ़्रेंच, 20% डच), जर्मनी की 2005 की सरकार को गठबंधन सरकार के रूप में पहचानना था, और श्रीलंका तथा बेल्जियम पर 4 अंक का केस अध्ययन था (तमिल माँगें, बहुसंख्यकवाद के परिणाम, बेल्जियम के प्रावधान)।\n"
  "- 3/5 अंक के प्रिय प्रश्न: बेल्जियम मॉडल, श्रीलंका में बहुसंख्यकवाद, युक्तिपरक और नैतिक तर्क, उदाहरण सहित सत्ता की साझेदारी के रूप।\n"
  "- सटीक प्रतिशत याद करें; विकल्प अक्सर इन्हें अदल-बदल देते हैं।",
  "- 2025-26ના નમૂનાના પ્રશ્નપત્રમાં પૂછાયું કે બેલ્જિયમની વંશીય રચનાનાં કયાં વિધાનો સાચાં છે (1% જર્મન; બ્રસેલ્સ 80% ફ્રેન્ચ, 20% ડચ), જર્મનીની 2005ની સરકારને ગઠબંધન સરકાર તરીકે ઓળખવાની હતી, અને શ્રીલંકા અને બેલ્જિયમ પર 4 ગુણનો કેસ અભ્યાસ હતો (તમિળ માગણીઓ, બહુમતીવાદનાં પરિણામો, બેલ્જિયમની જોગવાઈઓ).\n"
  "- 3/5 ગુણના પ્રિય પ્રશ્નો: બેલ્જિયમ મૉડલ, શ્રીલંકામાં બહુમતીવાદ, વ્યવહારુ અને નૈતિક કારણો, ઉદાહરણો સાથે સત્તાની ભાગીદારીનાં સ્વરૂપો.\n"
  "- ચોક્કસ ટકાવારી યાદ રાખો; વિકલ્પો ઘણી વાર તેને અદલબદલ કરે છે."),
 "s5.flash1.front": ("बहुसंख्यकवाद क्या है?", "બહુમતીવાદ શું છે?"),
 "s5.flash1.back": ("यह मान्यता कि बहुसंख्यक समुदाय अल्पसंख्यक की इच्छाओं और ज़रूरतों की अनदेखी करके जैसे चाहे देश पर शासन करे।", "એવી માન્યતા કે બહુમતી સમુદાય લઘુમતીની ઇચ્છાઓ અને જરૂરિયાતોની અવગણના કરીને મન ફાવે તેમ દેશ પર શાસન કરે."),
 "s5.flash2.front": ("बेल्जियम मॉडल के चार तत्व बताइए।", "બેલ્જિયમ મૉડલનાં ચાર તત્ત્વો જણાવો."),
 "s5.flash2.back": ("बराबर डच और फ़्रेंच मंत्री; राज्य सरकारों को अधिकार; बराबर ब्रसेल्स सरकार; सामुदायिक सरकारें।", "સરખા ડચ અને ફ્રેન્ચ પ્રધાનો; રાજ્ય સરકારોને સત્તા; સમાન બ્રસેલ્સ સરકાર; સમુદાય સરકારો."),
 "s5.flash3.front": ("सत्ता की साझेदारी के युक्तिपरक और नैतिक तर्कों में क्या अंतर है?", "સત્તાની ભાગીદારીનાં વ્યવહારુ અને નૈતિક કારણોમાં શો તફાવત છે?"),
 "s5.flash3.back": ("युक्तिपरक: इससे बेहतर परिणाम मिलते हैं (कम टकराव, स्थायित्व)। नैतिक: यह लोकतंत्र की आत्मा है और अपने-आप में मूल्यवान है।", "વ્યવહારુ: તેનાથી સારાં પરિણામો મળે છે (ઓછો સંઘર્ષ, સ્થિરતા). નૈતિક: તે લોકશાહીનો આત્મા છે અને પોતે જ મૂલ્યવાન છે."),
 "s5.flash4.front": ("नियंत्रण और संतुलन क्या है?", "નિયંત્રણ અને સંતુલન શું છે?"),
 "s5.flash4.back": ("ऐसी व्यवस्था जिसमें सरकार का हर अंग (विधायिका, कार्यपालिका, न्यायपालिका) दूसरों पर अंकुश रखता है, ताकि किसी के पास असीमित शक्ति न हो।", "એવી વ્યવસ્થા જેમાં સરકારનું દરેક અંગ (ધારાસભા, કારોબારી, ન્યાયતંત્ર) બીજાં પર અંકુશ રાખે છે, જેથી કોઈ પાસે અમર્યાદિત સત્તા ન રહે."),
}
